solution.solution.lua:
function with_defaults(t, defaults)
    return setmetatable(t, { __index = defaults })
end

function default_table(value)
    return setmetatable({}, { __index = function() return value end })
end

function read_only(t)
    return setmetatable({}, {
        __index = t,
        __len = function() return #t end,
        __newindex = function() error("attempt to change a read-only table", 2) end,
    })
end
